function ensureV2Worker(){
  if(v2Worker||!window.PokerV2?.FEATURES?.rangeV2Shadow)return v2Worker;
  v2Worker=new Worker("v2-worker.js");
  v2Worker.onmessage=event=>{
    const {key,result,error,warmed}=event.data||{};
    if(warmed)return;
    if(!key)return;
    if(result){
      const pending=v2ParallelPending.get(key);
      if(!pending)return;
      pending.base=result;
      recordV2BaseShadow(key,pending,result);
      finishV2Parallel(key);
    }else if(decisionButtonKey(lastState)===key){
      $("rangeV2Status").textContent=`V2旁路失败：${chineseError(error)}`;
    }
  };
  v2Worker.postMessage({key:"v2-worker-warmup",warmup:true});
  return v2Worker;
}

function ensureV2T1Workers(){
  while(v2T1Workers.length<1){
    const worker=new Worker("v2-t1-worker.js"),index=v2T1Workers.length;
    worker.onmessage=event=>{
      const {key,result,formalGate,error,warmed}=event.data||{};
      if(warmed)return;
      const pending=v2ParallelPending.get(key);
      if(!pending)return;
      pending.completed++;
      if(result){pending.parts.push(result);pending.workerFormalGate=formalGate||null}
      else pending.errors.push(error||`T1分片${index+1}失败`);
      finishV2Parallel(key);
    };
    worker.postMessage({key:`v2-t1-warmup-${index}`,warmup:true});
    v2T1Workers.push(worker);
  }
  return v2T1Workers;
}

function retireWorkersAfterFormalAdvice(items){
  const retiring=(items||[]).filter(Boolean);
  for(const worker of retiring)worker.onmessage=null;
  if(!retiring.length)return;
  const terminate=()=>retiring.forEach(worker=>worker.terminate());
  if(typeof requestIdleCallback==="function")requestIdleCallback(terminate,{timeout:250});
  else setTimeout(terminate,120);
}

